import { Check } from 'lucide-react';

import {
  StyledGenCenter,
  StyledGenCircle,
  StyledSpinner
} from '@/routes/_authenticated/start/-route.style';
import { GENERATE_PROGRESS_LABELS } from '@/routes/_authenticated/-components/GenerateInProgressScreen/GenerateInProgressScreen.constants';

type StepState = 'done' | 'active' | 'pending';

interface GenerateInProgressScreenProps {
  currentStep: number;
}

export function GenerateInProgressScreen({
  currentStep
}: GenerateInProgressScreenProps) {
  return (
    <StyledGenCenter>
      <StyledSpinner />
      <h2
        style={{
          fontSize: 20,
          fontWeight: 600,
          marginBottom: 12,
          letterSpacing: '-0.02em',
          color: '#25262C'
        }}
      >
        문서를 생성하고 있습니다
      </h2>
      <p
        style={{
          fontSize: 14,
          color: '#B5B9C4',
          textAlign: 'center',
          lineHeight: 1.6,
          marginBottom: 32,
          letterSpacing: '-0.02em'
        }}
      >
        양식과 프롬프트를 분석하여 문서를 생성 중입니다.
        <br />
        완료되면 자동으로 에디터로 이동합니다.
      </p>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
        {GENERATE_PROGRESS_LABELS.map((label, index) => {
          const state: StepState =
            index < currentStep
              ? 'done'
              : index === currentStep
                ? 'active'
                : 'pending';

          return (
            <div
              key={label}
              style={{ display: 'flex', alignItems: 'center', gap: 12, fontSize: 14 }}
            >
              <StyledGenCircle $state={state}>
                {state === 'done' ? <Check size={12} strokeWidth={3} /> : index + 1}
              </StyledGenCircle>
              <span
                style={{
                  color: state === 'pending' ? '#B5B9C4' : '#25262C',
                  fontWeight: state === 'active' ? 500 : 400,
                  fontSize: 14,
                  letterSpacing: '-0.02em'
                }}
              >
                {label}
              </span>
            </div>
          );
        })}
      </div>
    </StyledGenCenter>
  );
}
